// SoOptimal Contracting Pricing Calculator
const data = $input.all()[0].json;

// Pricing rates per sq ft
const rates = {
  residential: {
    installation: 2.50,
    repair: 45, // per hour
    finishing: 3.25,
    complete: 4.75
  },
  commercial: {
    installation: 2.25,
    repair: 55, // per hour  
    finishing: 3.00,
    complete: 4.25
  }
};

const minimums = {
  residential: 350,
  commercial: 1500,
  repair: 200
};

const projectType = data.projectType || 'residential';
const serviceType = data.serviceType || 'complete';
const sqFootage = parseInt(data.sqFootage) || 0;
const roomCount = parseInt(data.roomCount) || 1;

let basePrice;
if (serviceType === 'repair') {
  const estimatedHours = Math.max(sqFootage / 50, 2);
  basePrice = estimatedHours * rates[projectType][serviceType];
} else {
  basePrice = sqFootage * rates[projectType][serviceType];
}

// Apply minimum
basePrice = Math.max(basePrice, minimums[projectType]);

// Bulk discounts
if (sqFootage > 2000) basePrice *= 0.92;
if (sqFootage > 5000) basePrice *= 0.88;

// Room complexity
if (roomCount > 5) basePrice *= 1.1;

const lowPrice = Math.round(basePrice * 0.85);
const highPrice = Math.round(basePrice * 1.15);

return {
  ...data,
  pricing: {
    lowPrice,
    highPrice,
    basePrice: Math.round(basePrice),
    rate: rates[projectType][serviceType],
    projectType,
    serviceType,
    sqFootage
  }
};
